let trainingTab='mapa';
window.setTrainingTab=tab=>{if(!['mapa','exercicios','lista'].includes(tab))return;trainingTab=tab;render()};
const tabChooseMuscle=window.chooseMuscle;window.chooseMuscle=key=>{if(!muscleLibrary[key]||role!=='personal')return;trainingTab='exercicios';tabChooseMuscle(key)};
window.filterExerciseNames=value=>{const query=value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');let visible=0;document.querySelectorAll('.pane-exercicios #muscle-exercises .exercise').forEach(row=>{const text=row.textContent.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');row.hidden=!text.includes(query);if(!row.hidden)visible++});const message=$('#exercise-search-result');if(message)message.textContent=visible?`${visible} exercícios encontrados`:'Nenhum exercício encontrado. Tente outro nome.'};
const editFromTabs=window.editExercise;window.editExercise=(index,preset)=>{editFromTabs(index,preset);if(role!=='personal')return;const form=$('#exerciseForm'),submit=form.onsubmit;form.onsubmit=event=>{const prior=JSON.stringify(plan());submit(event);if(JSON.stringify(plan())!==prior){trainingTab='lista';render();toast('Exercício salvo na lista de treino do aluno.')}}};
const renderTrainingTabs=render;render=function(){renderTrainingTabs();if(role!=='personal'||page!=='treinos')return;const container=$('#content');const planHtml=container.lastElementChild.outerHTML.replace('onclick="editExercise()"','onclick="setTrainingTab(\'exercicios\')"');const labels=[['mapa','Mapa muscular'],['exercicios','Exercícios'],['lista','Treino do aluno']];container.innerHTML=heading('PLANO PERSONALIZADO',`Treino de ${esc(current().name.split(' ')[0])}.`,'Escolha o músculo, selecione os exercícios e organize o plano.',studentSelector())+`<div class="training-tabs" role="tablist" aria-label="Etapas da criação de treino">${labels.map(([key,label])=>`<button id="training-tab-${key}" role="tab" aria-controls="training-pane" aria-selected="${trainingTab===key}" class="${trainingTab===key?'primary':''}" onclick="setTrainingTab('${key}')">${label}${key==='lista'?` <span class="tab-count">${plan().length}</span>`:''}</button>`).join('')}</div><section id="training-pane" class="pane-${trainingTab}" role="tabpanel" aria-labelledby="training-tab-${trainingTab}">${trainingTab==='lista'?planHtml:musclePicker()}</section>`;if(trainingTab==='exercicios'){$('#muscle-exercises').insertAdjacentHTML('afterbegin',`<div class="exercise-search"><label>Buscar exercício<input type="search" placeholder="Ex.: supino inclinado" aria-label="Buscar exercício" oninput="filterExerciseNames(this.value)"></label><p id="exercise-search-result" role="status"></p></div>`)}else if(trainingTab==='mapa'){$('.body-panel').insertAdjacentHTML('beforeend',`<div class="anatomy-key"><span class="key-normal"></span> Grupo muscular <span class="key-selected"></span> Selecionado</div>`);$('.muscle-options').insertAdjacentHTML('beforeend',`<div class="selected-muscle-info"><span class="eyebrow">GRUPO SELECIONADO</span><h2>${esc(muscleLibrary[selectedMuscle].label)}</h2><p>${muscleLibrary[selectedMuscle].exercises.length} exercícios disponíveis. Toque no corpo ou escolha um grupo acima.</p><button class="primary" onclick="setTrainingTab('exercicios')">Ver exercícios ↗</button></div>`)}};

